// Some portions generated by Claude
/** Load batches: what each query or expansion added, for provenance and for telling a complete result from a LIMIT-cut one. */
import type { LoadBatch } from "./explorer-types.ts";
import { STAR_STRESS_BATCH_ID } from "./graph-fixtures.ts";

/**
 * The query's own LIMIT: the one outside every brace (a subquery's sits inside its braces), past strings, IRIs and
 * comments, which may hold braces or the word LIMIT.
 */
export function queryLimit(query: string) {
  const tokens =
    /"""[\s\S]*?"""|'''[\s\S]*?'''|"(?:[^"\\\n]|\\.)*"|'(?:[^'\\\n]|\\.)*'|<[^<>"{}|^`\\\s]*>|#[^\n]*|[{}]|\bLIMIT\s+(\d+)/gi;
  let depth = 0;
  let limit: number | null = null;
  for (const [token, value] of query.matchAll(tokens)) {
    if (token === "{") depth += 1;
    else if (token === "}") depth = Math.max(0, depth - 1);
    else if (value !== undefined && depth === 0) limit = Number(value);
  }
  return limit;
}

/** A result that stopped at a row limit: the one the page asked for, or the server's own cap (`byServer`). */
export type ResultCut = { limit: number; byServer: boolean };

/**
 * Whether a result of `rows` rows was cut: by the row limit the page passed (`rowLimit`), or by the Graph servlet's
 * cap on every result (`maxResultRows`, graph-max-result-rows). The servlet says whether it cut the result
 * (`truncated`, its rdf4j:truncated); without that word, a result as long as a limit may have been cut.
 */
export function resultCut(
  rows: number,
  rowLimit: number | undefined,
  maxResultRows: number | undefined,
  truncated?: boolean,
): ResultCut | null {
  if (truncated === false) return null;
  const byServer = maxResultRows !== undefined && (rowLimit === undefined || maxResultRows <= rowLimit);
  if (truncated === true) return byServer ? { limit: maxResultRows!, byServer } : { limit: rowLimit ?? rows, byServer };
  if (byServer && rows >= maxResultRows!) return { limit: maxResultRows!, byServer: true };
  if (rowLimit !== undefined && rows >= rowLimit) return { limit: rowLimit, byServer: false };
  return null;
}

export function createBatch(
  label: string,
  endpoint: string,
  query: string,
  tripleCount: number,
  cut: ResultCut | null = null,
) {
  const limit = cut?.limit ?? queryLimit(query);
  return {
    id: `batch-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
    label,
    endpoint,
    query,
    tripleCount,
    loadedAt: new Date().toISOString(),
    limit,
    complete: !cut && (limit === null || tripleCount < limit),
  } satisfies LoadBatch;
}

/** The status after a query loaded `statements`: how long it took, or that the result was cut and by whom. */
export function loadedStatus(statements: number, cut: ResultCut | null, milliseconds: number) {
  const count = statements.toLocaleString();
  if (cut?.byServer)
    return `Loaded the first ${count} statements: the server sends at most ${cut.limit.toLocaleString()} rows for a query, so the result may be cut. Page through it with LIMIT and OFFSET.`;
  if (cut) return `Loaded the first ${count} statements; the query has more.`;
  return `Loaded ${count} ${statements === 1 ? "statement" : "statements"} in ${milliseconds.toFixed(0)} ms.`;
}

export function createStarStressBatch(): LoadBatch {
  return {
    id: STAR_STRESS_BATCH_ID,
    label: "300-leaf interaction stress test",
    endpoint: "Deterministic local fixture",
    query:
      "# Synthetic graph: one root with 300 attached IRI, blank, typed-literal, and language-tagged leaf nodes.\n# Use this fixture to verify layout, filtering, panning, wheel zoom, and touch gestures.",
    tripleCount: 300,
    loadedAt: new Date().toISOString(),
    limit: null,
    complete: true,
  };
}
